class TwoSum:
    def __init__(self):
        self.values = set()
        self.sums = set()

    def add(self, number: int) -> None:
        for value in self.values:
            self.sums.add(number + value)
        self.values.add(number)

    def find(self, value: int) -> bool:
        return value in self.sums
